export type WorkspaceIconName = keyof typeof ICONS;

export function WorkspaceIcon({ name, size = 20, color = 'currentColor', className, style, title }: { name: WorkspaceIconName; size?: number; color?: string; className?: string; style?: CSSProperties; title?: string }) {
  const glyph = ICONS[name];
  return (
    <svg width={size} height={size} viewBox={glyph.viewBox} className={className} style={style} color={color} fill="none" aria-hidden={title ? undefined : true} role={title ? 'img' : undefined} focusable="false" dangerouslySetInnerHTML={{ __html: glyph.body }} />
  );
}
